package com.lemnt.trade.adapter.web;
import com.lemnt.common.core.domain.R;import com.lemnt.common.security.annotation.RequiresPermissions;import com.lemnt.trade.application.cmd.TradeOrderCreateCmd;import com.lemnt.trade.application.executor.*;import com.lemnt.trade.domain.model.TradeOrder;import jakarta.validation.Valid;import jakarta.validation.constraints.NotEmpty;import jakarta.validation.constraints.NotNull;import jakarta.validation.constraints.Positive;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.List;
@RestController @RequestMapping("/trade/orders") @RequiredArgsConstructor public class TradeOrderController {private final TradeOrderCreateCmdExe createExe;private final TradeOrderDetailQryExe detailExe;
 public record ItemReq(@NotNull @Positive Long productId,@NotNull @Positive Integer quantity){} public record CreateReq(@NotNull @Positive Long memberId,@NotEmpty List<@Valid ItemReq> items){} public record ItemRes(Long productId,String productCode,String productName,BigDecimal unitPrice,Integer quantity,BigDecimal lineAmount){} public record OrderRes(Long id,String orderNo,Long memberId,BigDecimal totalAmount,String status,List<ItemRes> items){static OrderRes from(TradeOrder o){return new OrderRes(o.id(),o.orderNo(),o.memberId(),o.totalAmount(),o.status(),o.items().stream().map(i->new ItemRes(i.productId(),i.productCode(),i.productName(),i.unitPrice(),i.quantity(),i.lineAmount())).toList());}}
 @PostMapping @RequiresPermissions("trade:order:create") public R<OrderRes> create(@Valid @RequestBody CreateReq req){var lines=req.items().stream().map(i->new TradeOrderCreateCmd.OrderLine(i.productId(),i.quantity())).toList();return R.ok(OrderRes.from(createExe.execute(new TradeOrderCreateCmd(req.memberId(),lines))));}
 @GetMapping("/{orderNo}") @RequiresPermissions("trade:order:query") public R<OrderRes> detail(@PathVariable String orderNo){TradeOrder o=detailExe.execute(orderNo);return o==null?R.fail("订单不存在"):R.ok(OrderRes.from(o));}
}